// — `scripts/test-i18n.mts` fails `npm test` if it drifts.
//
// House style: formal-neutral business Italian (Lei implied, never spelled
// out), verbs in the infinitive for buttons ("Salva" for a direct action,
// "Salvare" never), and brand names left untranslated (Growth Engine,
// Lead Miner™, Outreach Flow™, GrowthAI, Inbox, LinkedIn, Odoo).

// Typed structurally rather than importing `Dict` from i18n-dicts: that file
// imports this one, and the cycle deepened type instantiation enough to trip
// TS2589 in unrelated route handlers.
