  // Dispatcher failure playbook (/admin/reliability). Operator help text: cause + recommended action per failure mode.
  "rel.pb.noLi.cause": "La riga del lead non contiene primary_linkedin_url — o non è mai stata importata, o (per i lead di origine cliente) il dispatcher non è riuscito a decifrarla. Quest'ultimo era un bug ora risolto.",
  "rel.pb.noLi.action": "Riprova. Se falliscono di nuovo, il lead non ha davvero un URL LinkedIn — arricchisci la riga o rimuovilo dalla campagna.",
  "rel.pb.locked.cause": "Unipile ha restituito 422 perché il profilo LinkedIn del lead è privato, limitato da LinkedIn o è stato eliminato. Il venditore non ha problemi — il problema è il destinatario. Riprovare continuerà a fallire finché il profilo non torna raggiungibile (cosa che potrebbe non accadere mai).",
  "rel.pb.locked.action": "Non riprovare. Annulla la riga di campagna per questo lead e rimuovilo dal funnel oppure passa a un altro canale (email / chiamata) se hai quei dati. Contrassegna il lead come archiviato così le importazioni future non lo reinseriscono.",
  "rel.pb.rateLimit.title": "LinkedIn ha limitato il venditore per volume",
